    const kind = p.kind ?? 'plain';
    const r = p.highlight ? 9 : 6.5;
    out += `<g class="k-${kind}">${p.highlight ? `<circle cx="${r1(px)}" cy="${r1(py)}" r="16" class="halo"/>` : ''}<circle cx="${r1(px)}" cy="${r1(py)}" r="${r}" class="pt"/>`;
    const lx = p.labelSide === 'left' ? px - r - 8 : px + r + 8;
    out += textBlock(wrap(p.label, 150, 12.5, p.highlight ? 700 : 500), lx, py + 4, { size: 12.5, weight: p.highlight ? 700 : 500, cls: p.highlight ? 't1' : 't2', anchor: p.labelSide === 'left' ? 'end' : 'start', lh: 1.25 });
