    return `.k-${k} .nb{fill:${fill};stroke:${stroke}}.k-${k} .ac,.k-${k} .dot,.k-${k} .pt{fill:${stroke}}.k-${k} .ey{fill:${ey}}` +
      `.k-${k} .gb{fill:${fill};fill-opacity:.45;stroke:${stroke};stroke-opacity:.7}.k-${k} .bd{fill:${stroke}}` +
      `.k-${k}.e,.k-${k} .e{stroke:${k === 'plain' ? (mode === 'light' ? '#8A86A8' : '#7C88A3') : stroke}}.ah.k-${k}{fill:${k === 'plain' ? (mode === 'light' ? '#8A86A8' : '#7C88A3') : stroke}}` +
      `.k-${k} .lp{stroke:${k === 'plain' ? (mode === 'light' ? '#D9D6E8' : '#3A4A66') : stroke}}.k-${k} .qc.hl{fill:${fill}}.k-${k} .halo{fill:${stroke};fill-opacity:.18}`;
