// ── Diagram
export function diagram({ title, subtitle, description, width, height, legend = [], items }) {
  if (!title || !width || !height) throw new Error('diagram needs title, width and height');
  const totalW = width + PAD * 2;
  const totalH = HEADER + height + (legend.length ? LEGEND : 0) + PAD;
  const laid = items.map((it) => (it.type === 'node' ? layoutNode(it) : it));
  const boxes = new Map(laid.filter((i) => i.id && (i.type === 'node' || i.type === 'decision')).map((i) => [i.id, i]));
  for (const it of laid) {
    if (it.kind && !KINDS.includes(it.kind)) throw new Error(`${it.type} ${it.id ?? it.title ?? ''}: unknown kind "${it.kind}"`);
    if ((it.type === 'node' || it.type === 'decision') && (it.x + it.w > width + 0.5 || it.y + it.h > height + 0.5 || it.x < 0 || it.y < 0)) {
      throw new Error(`${it.type} "${it.id}" (${it.x},${it.y},${it.w}x${it.h}) falls outside the ${width}x${height} content area`);
    }
  }
  const edges = laid.filter((i) => i.type === 'edge').map((e) => renderEdge(e, boxes));
  const body = [
    ...laid.filter((i) => i.type === 'group').map(renderGroup),
    ...laid.filter((i) => i.type === 'quadrant').map(renderQuadrant),
    ...edges.map((e) => e.path),
    ...laid.filter((i) => i.type === 'node').map(renderNode),
    ...laid.filter((i) => i.type === 'decision').map(renderDecision),
    ...laid.filter((i) => i.type === 'note').map(renderNote),
    ...edges.map((e) => e.label),
  ].join('\n');

  let legendSvg = '';
  if (legend.length) {
    let lx = PAD; const ly = HEADER + height + 24;
    legendSvg = `<line x1="${PAD}" y1="${ly - 12}" x2="${totalW - PAD}" y2="${ly - 12}" class="rule"/>` + legend.map((l) => {
      const s = `<g class="k-${l.kind}"><rect x="${lx}" y="${ly + 2}" width="14" height="14" rx="4" class="nb"/>${textBlock([l.label], lx + 22, ly + 13.5, { size: 12, cls: 't2' })}</g>`;
      lx += 22 + textWidth(l.label, 12) + 28;
      return s;
    }).join('');
  }
  const markers = KINDS.map((k) => `<marker id="ah-${k}" viewBox="0 0 10 10" refX="8.5" refY="5" markerWidth="8" markerHeight="8" orient="auto-start-reverse"><path d="M1,1 L9,5 L1,9 Z" class="ah k-${k}"/></marker>`).join('');
  const desc = description ?? subtitle ?? title;
  return `<svg xmlns="http://www.w3.org/2000/svg" width="${totalW}" height="${totalH}" viewBox="0 0 ${totalW} ${totalH}" role="img" aria-labelledby="title desc">
<title id="title">${esc(title)}</title>
<desc id="desc">${esc(desc)}</desc>
<style>${css()}</style>
<defs><filter id="sh" x="-10%" y="-10%" width="120%" height="140%"><feDropShadow dx="0" dy="1.5" stdDeviation="2" flood-color="#14122B" flood-opacity="0.07"/></filter>${markers}</defs>
<rect x="0.75" y="0.75" width="${totalW - 1.5}" height="${totalH - 1.5}" rx="18" class="cv" stroke-width="1.5"/>
${textBlock([title], PAD, 46, { size: 20, weight: 700, cls: 't1' })}
${subtitle ? textBlock([subtitle], PAD, 68, { size: 13, cls: 't2' }) : ''}
<g transform="translate(${PAD},${HEADER})">
${body}
</g>
${legendSvg}
</svg>
`;
}
